package com.zamotkin.extrahealthgarmin.omron.data

import androidx.room.Entity
import androidx.room.Index
import androidx.room.PrimaryKey

/**
 * Room row for one blood-pressure reading (task tefal2garmin-4uy, epic
 * tefal2garmin-939; sourceId column added by task
 * tefal2garmin-app-redesign-v3-xlg.2). Mirrors
 * [com.zamotkin.extrahealthgarmin.omron.BloodPressureReading]
 * plus persistence-only state: the auto-generated [id], the [synced] flag
 * and the [sourceId] of the connected source the reading came through.
 *
 * The unique index on (timestampEpochSec, userSlot, sourceId) is the dedup
 * key — a device re-serves the same records on every read, so insert-ignore
 * against this index is what makes re-reads idempotent, and the same
 * measurement read through two different sources is two rows. The
 * Garmin-side dedup journal stays keyed (timestamp, userSlot) — see
 * [com.zamotkin.extrahealthgarmin.garmin.BpUploadJournal].
 *
 * @property id row id, generated by SQLite on insert
 * @property timestampEpochSec measurement time, seconds since Unix epoch (UTC)
 * @property systolic systolic pressure, mmHg
 * @property diastolic diastolic pressure, mmHg
 * @property pulse heart rate, beats per minute
 * @property mov movement-during-measurement flag
 * @property ihb irregular-heartbeat flag
 * @property userSlot Omron user slot: 1 or 2
 * @property sourceId id of the connected source (the ConnectedSource UUID;
 *   rows written before sources existed default to [LEGACY_SOURCE_ID])
 * @property synced whether the record was already uploaded to Garmin
 */
@Entity(
    tableName = "blood_pressure_records",
    indices = [Index(value = ["timestampEpochSec", "userSlot", "sourceId"], unique = true)]
)
data class BloodPressureRecordEntity(
    @PrimaryKey(autoGenerate = true) val id: Long = 0,
    val timestampEpochSec: Long,
    val systolic: Int,
    val diastolic: Int,
    val pulse: Int,
    val mov: Boolean,
    val ihb: Boolean,
    val userSlot: Int,
    val sourceId: String = LEGACY_SOURCE_ID,
    val synced: Boolean = false
) {
    companion object {
        /**
         * Source identity of the pre-sources Omron pipeline (the single
         * monitor the ui/omron screen reads until task xlg.6 absorbs it):
         * the default of [sourceId], so legacy call sites that construct or
         * store rows without a source keep compiling and their rows keep
         * deduping among themselves.
         */
        const val LEGACY_SOURCE_ID = "omron"
    }
}
